:root {
  --ink: #30251f;
  --paper: #fffaf0;
  --crust: #d78949;
  --sage: #476f57;
  --line: #e7cda9;
}

.proof-card {
  box-sizing: border-box;
  width: 440px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.proof-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: var(--crust);
}

.loaf {
  font-size: 28px;
}

.eyebrow {
  margin: 0 0 2px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

.proof-header h1 {
  margin: 0;
  font-size: 19px;
  line-height: 1.1;
}

.proof-body {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 16px;
}

.timer {
  margin: 0;
  font-size: 30px;
  font-weight: 700;
  color: var(--sage);
}

.status {
  margin: 0;
  font-size: 13px;
  line-height: 1.45;
}

.proof-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
  font-size: 12px;
}

.proof-footer button {
  border: 0;
  border-radius: 7px;
  padding: 7px 10px;
  background: var(--sage);
  color: var(--paper);
  font-weight: 700;
}
